1	//go:build integration
2	
3	package integration
4	
5	import (
6		"bytes"
7		"encoding/json"
8		"fmt"
9		"os/exec"
10		"testing"
11		"time"
12	
13		"github.com/entireio/cli/cmd/entire/cli/benchutil"
14		"github.com/entireio/cli/cmd/entire/cli/testutil"
15	)
16	
17	// BenchmarkHookSessionStart measures the end-to-end latency of the
18	// "entire hooks claude-code session-start" subprocess.
19	//
20	// Each sub-benchmark isolates a single scaling dimension that appears
21	// in the session-start hot path (see hook_registry.go → lifecycle.go):
22	//
23	//   - Sessions:      store.List() called 2x, ReadDir + ReadFile + unmarshal + repo.Reference() per file
24	//   - SessionsXRefs: sessions × refs interaction (repo.Reference scans packed-refs per session)
25	//   - PackedRefs:    go-git PlainOpen + repo.Reference cost with many packed refs
26	//   - GitObjects:    go-git PlainOpen cost with large .git/objects packfile
27	//   - Subprocess:    isolates git rev-parse and binary spawn overhead
28	//
29	// Run all:
30	//
31	//	go test -tags=integration -bench=BenchmarkHookSessionStart -benchtime=3x -run='^$' -timeout=10m ./cmd/entire/cli/integration_test/...
32	//
33	// Run one dimension:
34	//
35	//	go test -tags=integration -bench=BenchmarkHookSessionStart/Subprocess -benchtime=5x -run='^$' ./cmd/entire/cli/integration_test/...
36	func BenchmarkHookSessionStart(b *testing.B) {
37		b.Run("Sessions", benchSessions)
38		b.Run("SessionsXRefs", benchSessionsXRefs)
39		b.Run("PackedRefs", benchPackedRefs)
40		b.Run("GitObjects", benchGitObjects)
41		b.Run("Subprocess", benchSubprocessOverhead)
42	}
43	
44	// benchSessions scales session state files in .git/entire-sessions/.
45	// listAllSessionStates() is called twice: once in FindMostRecentSession (logging init),
46	// once in CountOtherActiveSessionsWithCheckpoints. Each call does
47	// ReadDir + (ReadFile + JSON unmarshal + repo.Reference) per file.
48	func benchSessions(b *testing.B) {
49		for _, n := range []int{0, 1, 5, 10, 25, 50, 100, 200} {
50			b.Run(fmt.Sprintf("%d", n), func(b *testing.B) {
51				repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{
52					FileCount:     10,
53					FeatureBranch: "feature/bench",
54				})
55				for range n {
56					repo.CreateSessionState(b, benchutil.SessionOpts{
57						StepCount:    3,
58						FilesTouched: []string{"src/file_000.go", "src/file_001.go"},
59					})
60				}
61				runSessionStartHook(b, repo)
62			})
63		}
64	}
65	
66	// benchSessionsXRefs tests the interaction between session count and ref count.
67	// For each session, listAllSessionStates calls repo.Reference() which scans packed-refs.
68	// Cost should be O(sessions × packed-refs-size).
69	func benchSessionsXRefs(b *testing.B) {
70		type scenario struct {
71			sessions int
72			refs     int
73		}
74		scenarios := []scenario{
75			{5, 10},
76			{5, 500},
77			{50, 10},
78			{50, 500},
79			{100, 500},
80		}
81		for _, sc := range scenarios {
82			b.Run(fmt.Sprintf("s%d_r%d", sc.sessions, sc.refs), func(b *testing.B) {
83				repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{
84					FileCount:     10,
85					FeatureBranch: "feature/bench",
86				})
87				for range sc.sessions {
88					repo.CreateSessionState(b, benchutil.SessionOpts{
89						StepCount:    3,
90						FilesTouched: []string{"src/file_000.go"},
91					})
92				}
93				repo.SeedBranches(b, "feature/team-", sc.refs)
94				repo.PackRefs(b)
95				runSessionStartHook(b, repo)
96			})
97		}
98	}
99	
100	// benchPackedRefs scales the number of packed git refs (branches).
101	// go-git PlainOpen reads packed-refs, and every repo.Reference() call
102	// scans it. Session count held constant at 5.
103	func benchPackedRefs(b *testing.B) {
104		for _, n := range []int{0, 50, 200, 500, 1000, 2000} {
105			b.Run(fmt.Sprintf("%d", n), func(b *testing.B) {
106				repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{
107					FileCount:     10,
108					FeatureBranch: "feature/bench",
109				})
110				for range 5 {
111					repo.CreateSessionState(b, benchutil.SessionOpts{
112						StepCount:    3,
113						FilesTouched: []string{"src/file_000.go"},
114					})
115				}
116				if n > 0 {
117					repo.SeedBranches(b, "feature/team-", n)
118					repo.PackRefs(b)
119				}
120				runSessionStartHook(b, repo)
121			})
122		}
123	}
124	
125	// benchGitObjects scales the .git/objects packfile size.
126	// go-git PlainOpen parses pack indexes; large packs may slow it down.
127	// This also affects repo.Head() and repo.Reference() indirectly.
128	func benchGitObjects(b *testing.B) {
129		for _, n := range []int{0, 1000, 5000, 10000} {
130			b.Run(fmt.Sprintf("%d", n), func(b *testing.B) {
131				repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{
132					FileCount:     10,
133					FeatureBranch: "feature/bench",
134				})
135				for range 5 {
136					repo.CreateSessionState(b, benchutil.SessionOpts{
137						StepCount:    3,
138						FilesTouched: []string{"src/file_000.go"},
139					})
140				}
141				if n > 0 {
142					repo.SeedGitObjects(b, n)
143				}
144				runSessionStartHook(b, repo)
145			})
146		}
147	}
148	
149	// benchSubprocessOverhead isolates the cost of subprocess spawns that happen
150	// during session-start. The hook calls git rev-parse multiple times (some cached,
151	// some not) plus spawns the entire binary itself. This benchmark measures each
152	// component so we can see what fraction of the total is subprocess overhead.
153	func benchSubprocessOverhead(b *testing.B) {
154		repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{
155			FileCount:     10,
156			FeatureBranch: "feature/bench",
157		})
158	
159		// 1. Bare git rev-parse round-trip
160		b.Run("GitRevParse_1x", func(b *testing.B) {
161			b.ResetTimer()
162			for range b.N {
163				start := time.Now()
164				cmd := exec.Command("git", "rev-parse", "--show-toplevel")
165				cmd.Dir = repo.Dir
166				cmd.Env = testutil.GitIsolatedEnv()
167				if output, err := cmd.CombinedOutput(); err != nil {
168					b.Fatalf("git rev-parse failed: %v\n%s", err, output)
169				}
170				b.ReportMetric(float64(time.Since(start).Milliseconds()), "ms/op")
171			}
172		})
173	
174		// 2. Seven sequential git rev-parse calls (pre-optimization baseline)
175		b.Run("GitRevParse_7x", func(b *testing.B) {
176			b.ResetTimer()
177			for range b.N {
178				start := time.Now()
179				for range 7 {
180					cmd := exec.Command("git", "rev-parse", "--show-toplevel")
181					cmd.Dir = repo.Dir
