65	func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
66		// Initialize structured logger so logging.Warn/Info write to .entire/logs/ not stderr.
67		if err := logging.Init(ctx, sessionID); err != nil {
68			// Init failed — logging will use stderr fallback, non-fatal.
69			_ = err
70		}
71	
72		logCtx := logging.WithComponent(ctx, "attach")
73	
74		// Open repository once — shared across all operations.
75		repo, err := openRepository(ctx)
76		if err != nil {
77			return err
78		}
79	
80		existingState, err := validateAttachPreconditions(ctx, repo, sessionID)
81		if err != nil {
82			return err
83		}
84	
85		headCommit, err := getHeadCommit(repo)
86		if err != nil {
87			return err
88		}
89	
90		// If session already has a checkpoint, just offer to link it.
91		if existingState != nil && !existingState.LastCheckpointID.IsEmpty() {
92			cpID := existingState.LastCheckpointID.String()
93			fmt.Fprintf(w, "Session %s already has checkpoint %s\n", sessionID, cpID)
94			if err := promptAmendCommit(logCtx, w, headCommit, cpID, force); err != nil {
95				logging.Warn(logCtx, "failed to amend commit", "error", err)
96				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", cpID)
97			}
98			return nil
99		}
100	
101		// Resolve agent and transcript path.
102		ag, transcriptPath, err := resolveAgentAndTranscript(logCtx, w, sessionID, agentName, existingState)
103		if err != nil {
104			return err
105		}
106	
107		transcriptData, err := ag.ReadTranscript(transcriptPath)
108		if err != nil {
109			return fmt.Errorf("failed to read transcript: %w", err)
110		}
111	
112		// Normalize Gemini transcripts for storage.
113		storedTranscript := transcriptData
114		if ag.Type() == agent.AgentTypeGemini {
115			if normalized, normErr := geminicli.NormalizeTranscript(transcriptData); normErr == nil {
116				storedTranscript = normalized
117			} else {
118				logging.Warn(logCtx, "failed to normalize Gemini transcript, storing raw", "error", normErr)
119			}
120		}
121	
122		meta := extractTranscriptMetadata(transcriptData)
123	
124		// Determine checkpoint ID: reuse from HEAD if one exists, otherwise generate new.
125		checkpointID, isExistingCheckpoint := resolveCheckpointID(headCommit)
126	
127		// Write directly to entire/checkpoints/v1.
128		store := cpkg.NewGitStore(repo)
129	
130		author, err := GetGitAuthor(ctx)
131		if err != nil {
132			return fmt.Errorf("failed to get git author: %w", err)
133		}
134	
135		var prompts []string
136		if meta.FirstPrompt != "" {
137			prompts = []string{meta.FirstPrompt}
138		}
139	
140		tokenUsage := agent.CalculateTokenUsage(logCtx, ag, transcriptData, 0, "")
141	
142		if err := store.WriteCommitted(ctx, cpkg.WriteCommittedOptions{
143			CheckpointID: checkpointID,
144			SessionID:    sessionID,
145			Strategy:     strategy.StrategyNameManualCommit,
146			Transcript:   storedTranscript,
147			Prompts:      prompts,
148			AuthorName:   author.Name,
149			AuthorEmail:  author.Email,
150			Agent:        ag.Type(),
151			Model:        meta.Model,
152			TokenUsage:   tokenUsage,
153		}); err != nil {
154			return fmt.Errorf("failed to write checkpoint: %w", err)
155		}
156	
157		// Create or update session state.
158		if err := saveAttachSessionState(logCtx, existingState, sessionID, ag.Type(), transcriptPath, checkpointID, meta, tokenUsage); err != nil {
159			logging.Warn(logCtx, "failed to save session state", "error", err)
160		}
161	
162		fmt.Fprintf(w, "Attached session %s\n", sessionID)
163		if isExistingCheckpoint {
